require __DIR__.'/phase-6-7-stage.php';$private=__DIR__.'/../docs/audit/private/';$check=static function(bool $ok,string $message){if(!$ok)throw new RuntimeException($message);};
try{$owner=User::findOrFail(DB::table('tenant_memberships')->where('status','active')->orderBy('id')->value('user_id'));$tenant=app(TenantService::class)->create($owner,['name'=>'Phase 6/7 isolated fixture','slug'=>'finance-'.bin2hex(random_bytes(6)),'timezone'=>'Asia/Karachi','currency_code'=>'PKR']);DB::table('tenant_subscriptions')->where('tenant_id',$tenant)->update(['grandfathered'=>true,'status'=>'active']);
$report=app(TenantContext::class)->runFor($tenant,$owner->id,function()use($tenant,$owner,$private,$check){$put=fn($table,$data)=>DB::table($table)->insertGetId($data+['tenant_id'=>$tenant,'created_at'=>now(),'updated_at'=>now()]);$branch=DB::table('branches')->where('tenant_id',$tenant)->value('id');$location=DB::table('locations')->where('tenant_id',$tenant)->value('id');$preview=app(CutoverService::class)->preview($branch);app(CutoverService::class)->activate($branch,['idempotency_key'=>'fixture-activation','preview_hash'=>$preview['preview_hash'],'confirm_locations'=>true,'allow_credit'=>true]);$unit=$put('catalog_units',['name'=>'Each','code'=>'EA','quantity_precision'=>0]);$product=$put('catalog_products',['name'=>'Fixture item','product_type'=>'simple','track_inventory'=>true]);$variant=$put('catalog_variants',['product_id'=>$product,'base_unit_id'=>$unit,'sku'=>'FINANCE-FIXTURE','default_cost'=>'10','default_price'=>'12.35','tracking_mode'=>'none']);$register=$put('cash_registers',['name'=>'Fixture register','branch_id'=>$branch,'location_id'=>$location]);$shift=app(SaleService::class)->open(['idempotency_key'=>'fixture-shift','register_id'=>$register,'opening_cash'=>'100.00'])['id'];$cash=DB::table('payment_methods')->where('tenant_id',$tenant)->where('code','CASH')->value('id');$stock=app(InventoryPostingService::class);$sale=app(SaleService::class);$returns=app(ReturnService::class);
$race=function(array $jobs)use($tenant,$owner,$private,$check){$run=$private.'phase67-run-'.bin2hex(random_bytes(8));mkdir($run,0700);$workers=[];$paths=[];foreach($jobs as $job){$path=$run.'/job-'.bin2hex(random_bytes(5)).'.json';file_put_contents($path,json_encode($job+['tenant'=>$tenant,'owner'=>$owner->id],JSON_THROW_ON_ERROR));$paths[]=$path;$worker=new Process([PHP_BINARY,__DIR__.'/phase-6-7-worker.php',$path],__DIR__.'/..');$worker->setTimeout(90);$worker->start();$workers[]=$worker;}$until=microtime(true)+40;while(count(array_filter($paths,fn($p)=>is_file($p.'.ready')))!==count($paths)){if(microtime(true)>$until||array_filter($workers,fn($w)=>!$w->isRunning()))throw new RuntimeException('Worker barrier failed.');usleep(20000);}file_put_contents($run.'/start','start');$out=[];foreach($workers as $w){$w->wait();$data=json_decode($w->getOutput(),true,512,JSON_THROW_ON_ERROR);$check($w->isSuccessful()&&$data['status']!=='error','Worker error: '.json_encode($data));$out[]=$data;}return $out;};
$newSale=function()use($stock,$location,$variant,$sale,$shift,$cash){$stock->post($location,$variant,'1','adjustment','fixture',1,'fixture:'.bin2hex(random_bytes(8)));$q=$sale->quote(['cash_session_id'=>$shift,'items'=>[['variant_id'=>$variant,'qty'=>'1']]]);return $sale->checkout(['idempotency_key'=>'sale:'.bin2hex(random_bytes(6)),'quote_id'=>$q['id'],'payments'=>[['method_id'=>$cash,'amount'=>'12.35']]])['id'];};
$draft=function($saleId,$kind='return')use($returns){$line=DB::table('sale_items')->where('sale_id',$saleId)->value('id');$id=$returns->create($saleId,['idempotency_key'=>'ret:'.bin2hex(random_bytes(6)),'reason'=>'Isolated race fixture','kind'=>$kind,'items'=>[['sale_item_id'=>$line,'qty'=>'1','disposition'=>'resellable']]])['id'];$returns->approve($id);return $id;};
