$second=$newSale();$ret=$draft($second);$returns->post($ret);$different=$race([$refundJob($ret,'refund-first-key'),$refundJob($ret,'refund-second-key')]);$statuses=array_column($different,'status');sort($statuses);$check($statuses===['conflict','ok'],'Different keys cannot exceed collected refund entitlement.');
$third=$newSale();$normal=$draft($third);$cancel=$draft($third,'cancel');$cancelRace=$race([['operation'=>'return','source_id'=>$normal],['operation'=>'return','source_id'=>$cancel]]);$statuses=array_column($cancelRace,'status');sort($statuses);$check($statuses===['conflict','ok'],'Return and cancellation cannot both restock a sale.');
$fourth=$newSale();$ret=$draft($fourth);$returns->post($ret);$closeRace=$race([['operation'=>'close','source_id'=>$shift,'input'=>['idempotency_key'=>'close-race-key','counted_cash'=>'100.00']],$refundJob($ret,'close-race-refund')]);$check($closeRace[0]['status']==='ok','Closing must produce one coherent cash snapshot.');$summary=app(CashService::class)->summary($shift);$stored=DB::table('cash_sessions')->where('id',$shift)->first();$check(bccomp((string)$stored->expected_cash,$summary['expected_cash'],4)===0,'No financial posting may occur after closing cash snapshot.');
$plan=DB::table('plans')->insertGetId(['code'=>'fixture-'.bin2hex(random_bytes(4)),'name'=>'Isolated limit fixture','public'=>false,'active'=>true,'created_at'=>now(),'updated_at'=>now()]);foreach(\App\Domain\Billing\BillingService::FEATURES as $f)DB::table('plan_entitlements')->insert(['plan_id'=>$plan,'feature_code'=>$f,'enabled'=>true,'limit_value'=>$f==='products'?2:null]);$price=DB::table('plan_prices')->insertGetId(['plan_id'=>$plan,'code'=>'fixture-'.bin2hex(random_bytes(4)),'currency_code'=>'USD','interval'=>'perpetual','amount'=>'0','created_at'=>now(),'updated_at'=>now()]);DB::table('tenant_subscriptions')->where('tenant_id',$tenant)->update(['plan_price_id'=>$price]);$input=['name'=>'Quota item','product_type'=>'simple','track_inventory'=>true,'variant'=>['sku'=>'LIMIT-A','base_unit_id'=>$unit,'default_cost'=>'0','default_price'=>'1','tracking_mode'=>'none']];$input2=$input;$input2['variant']['sku']='LIMIT-B';$limits=$race([['operation'=>'product','input'=>$input],['operation'=>'product','input'=>$input2]]);$statuses=array_column($limits,'status');sort($statuses);$check($statuses===['conflict','ok'],'Concurrent catalog requests cannot exceed a plan resource limit.');$inv=$stock->reconcile();$check($inv['reconciled'],'Stock ledger must reconcile.');$fin=app(ReportService::class)->report(['from'=>now()->subDay()->toDateString(),'to'=>now()->addDay()->toDateString()]);$check($fin['reconciled'],'Sale/payment/return/refund totals must reconcile.');return ['fixture_tenant'=>$tenant,'return_race'=>$postRace,'duplicate_refund'=>$same,'overrefund_race'=>$different,'cancel_return_race'=>$cancelRace,'close_refund_race'=>$closeRace,'plan_limit_race'=>$limits,'inventory'=>$inv,'financial_reconciled'=>$fin['reconciled']];});
file_put_contents($private.'phase-6-7-concurrency.json',json_encode(['passed'=>true,'database'=>$stageDatabase,'verified_at'=>date(DATE_ATOM),'separate_processes'=>true]+$report,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));echo 'MariaDB return/refund/cancellation/shift-close and plan-limit races passed; stock and financial totals reconcile.'.PHP_EOL;
}catch(Throwable $e){file_put_contents($private.'phase-6-7-concurrency-error.json',json_encode(['class'=>$e::class,'message'=>$e->getMessage(),'file'=>$e->getFile(),'line'=>$e->getLine()],JSON_PRETTY_PRINT));fwrite(STDERR,'Phase 6–7 concurrency verification failed. Inspect private evidence.'.PHP_EOL);exit(1);}
